<script>
(()=>{const backdrop=document.getElementById('shift-close-backdrop'),drawer=document.getElementById('shift-close-drawer'),form=document.getElementById('shift-close-form'),meta=document.getElementById('shift-close-meta'),fields=document.getElementById('shift-close-readings');if(!backdrop||!drawer||!form)return;const close=()=>{backdrop.hidden=true;drawer.hidden=true;document.body.classList.remove('shift-drawer-open')};document.addEventListener('click',event=>{const trigger=event.target.closest('[data-close-shift]');if(trigger){let readings=[];try{readings=JSON.parse(trigger.dataset.readings||'[]')}catch{}fields.replaceChildren();for(const reading of readings){const group=document.createElement('div'),label=document.createElement('label'),input=document.createElement('input'),opening=Number(reading.opening)||0;group.className='mb-3';label.className='form-label';label.textContent=`${reading.name} closing · opening ${opening.toFixed(3)}`;input.className='form-control';input.type='number';input.name=`readings[${reading.id}][closing]`;input.min=String(opening);input.step='0.001';input.required=true;group.append(label,input);fields.append(group)}meta.textContent=trigger.dataset.shiftLabel||'';form.action=form.dataset.urlTemplate.replace('__SHIFT__',encodeURIComponent(trigger.dataset.shiftId));backdrop.hidden=false;drawer.hidden=false;document.body.classList.add('shift-drawer-open');fields.querySelector('input')?.focus();return}if(event.target===backdrop||event.target.closest('[data-close-shift-drawer]'))close()});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!drawer.hidden)close()})})();
</script>
