<script>
(()=>{const shift=document.getElementById('assign_shift'),nozzle=document.getElementById('assign_nozzle'),operator=document.getElementById('assign_operator'),opening=document.getElementById('assign_opening'),form=document.getElementById('assign-nozzle-form'),submit=document.getElementById('assign-submit');if(!shift||!form)return;function sync(){const selected=shift.selectedOptions[0],station=selected?.dataset.station,date=selected?.dataset.date;nozzle.value='';operator.value='';nozzle.disabled=!station;operator.disabled=!station;opening.disabled=true;opening.value='0.000';for(const option of [...nozzle.options].slice(1)){const rightStation=option.dataset.station===station,busy=(option.dataset.busy||'').split(',').some(item=>item.startsWith(date+':')),hasRate=(option.dataset.rates||'').split(',').includes(date);option.hidden=!rightStation;option.disabled=!rightStation||busy||!hasRate;option.textContent=option.dataset.fuel?`${option.textContent.split(' · ')[0]} · ${option.dataset.fuel}${busy?' · Already assigned':(!hasRate?' · Rate not set':'')}`:option.textContent}for(const option of [...operator.options].slice(1)){const assigned=(option.dataset.stations||'').split(',').includes(station);option.hidden=!assigned;option.disabled=!assigned}if(selected?.dataset.operator)operator.value=selected.dataset.operator;submit.disabled=true}shift.addEventListener('change',sync);nozzle.addEventListener('change',()=>{const option=nozzle.selectedOptions[0];opening.disabled=!option?.value;if(option?.value)opening.value=option.dataset.opening||'0.000';submit.disabled=!(shift.value&&nozzle.value&&operator.value)});operator.addEventListener('change',()=>submit.disabled=!(shift.value&&nozzle.value&&operator.value));form.addEventListener('submit',event=>{if(!shift.value||!nozzle.value||!operator.value){event.preventDefault();return}form.action=`/shifts/${shift.value}/assign-nozzle`});sync()})();
</script>
<style>.closing-row{background:#f7f9f7!important}.closing-row details>summary{font-size:11px;font-weight:500;color:#335344;cursor:pointer;padding:5px}.assign-panel{padding:20px}.assign-heading{margin-bottom:18px}.assign-grid{display:grid;grid-template-columns:1.2fr 1.1fr 1fr 1fr auto;gap:13px;align-items:end}.assign-action .btn{height:39px;white-space:nowrap}.assign-empty{padding:15px;background:#f6f8f6;border-radius:6px;font-size:11px;color:#75847b}@media(max-width:1000px){.assign-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.assign-action{grid-column:1/-1}}@media(max-width:575px){.assign-grid{grid-template-columns:1fr}.assign-action{grid-column:auto}}.shift-close-backdrop{position:fixed;inset:0;z-index:1059;background:rgba(8,28,21,.46)}.shift-close-drawer{position:fixed;z-index:1060;inset:0 0 0 auto;width:min(520px,100vw);overflow-y:auto;padding:27px 24px;background:#fff;box-shadow:-14px 0 40px #102b202e}.shift-close-backdrop[hidden],.shift-close-drawer[hidden]{display:none}.shift-drawer-head{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;padding-bottom:17px;margin-bottom:17px;border-bottom:1px solid #edf1ee}.shift-drawer-head h2{font-size:19px;font-weight:600;margin:0 0 5px;color:#18372d}.shift-drawer-actions{display:flex;justify-content:flex-end;gap:9px;padding-top:18px;margin-top:22px;border-top:1px solid #edf1ee}body.shift-drawer-open{overflow:hidden}@media(max-width:575px){.shift-close-drawer{padding:22px 17px}}</style>
